function section(id, index, title, body) {
  // Если у короткого раздела заголовок совпадает с подписью в оглавлении,
  // допускаем компактный вызов section(id, index, body), но не выводим
  // техническое undefined в учебный текст.
  if (body === undefined) {
    body = title;
    title = index.replace(/^\d+\s*\/\s*/, '');
    title = title.charAt(0).toUpperCase() + title.slice(1);
  }
  return `<section class="theory-block algorithm-section" id="${id}"><small>${index}</small><h2>${title}</h2>${body}</section>`;
}

function reference(label, href) {
  return `<a class="theory-reference" href="${href}" target="_blank" rel="noreferrer">${label} <span>↗</span></a>`;
}

function sources(title, links) {
  return `<div class="theory-sources"><span>${title}</span>${links.join('')}</div>`;
}


function knnVisual() {
  return `<figure class="theory-visual" aria-labelledby="knn-visual-caption"><svg viewBox="0 0 720 300" role="img" aria-label="Окрестность точки в методе ближайших соседей"><title>Голосование ближайших соседей</title><path class="theory-grid" d="M60 36V246M60 246H678M60 88H678M60 140H678M60 192H678M184 36V246M308 36V246M432 36V246M556 36V246M678 36V246"/><circle class="theory-neighborhood" cx="361" cy="153" r="103"/><g class="theory-class-a"><circle cx="255" cy="172" r="9"/><circle cx="281" cy="124" r="9"/><circle cx="307" cy="194" r="9"/><circle cx="326" cy="112" r="9"/></g><g class="theory-class-b"><rect x="404" y="111" width="18" height="18" rx="3"/><rect x="442" y="145" width="18" height="18" rx="3"/><rect x="420" y="189" width="18" height="18" rx="3"/><rect x="481" y="183" width="18" height="18" rx="3"/></g><path class="theory-neighbor-link" d="M361 153L326 112M361 153L404 120M361 153L307 194"/><path class="theory-query" d="M361 137 l5 11 12 1 -9 8 3 12 -11 -6 -11 6 3 -12 -9 -8 12 -1z"/><text x="70" y="25">время решения</text><text x="584" y="274">сложность</text><text x="374" y="146">z</text><text x="475" y="78">N₃(z)</text></svg><figcaption id="knn-visual-caption">Запрос z получает класс по локальной окрестности. Цвет дополнен формой: круг и квадрат.</figcaption></figure>`;
}

function treeVisual() {
  return `<figure class="theory-visual" aria-labelledby="tree-visual-caption"><svg viewBox="0 0 720 300" role="img" aria-label="Схема дерева с предикатами"><title>Предикаты в решающем дереве</title><path class="theory-tree-edge" d="M360 65L206 145M360 65L514 145M206 145L134 232M206 145L278 232M514 145L442 232M514 145L586 232"/><g class="theory-tree-node"><rect x="265" y="34" width="190" height="60" rx="12"/><text x="360" y="59" text-anchor="middle">Доход клиента ≤ 5.1</text><text x="360" y="78" text-anchor="middle">да / нет</text></g><g class="theory-tree-node"><rect x="115" y="116" width="182" height="58" rx="12"/><text x="206" y="141" text-anchor="middle">Рейтинг ≤ 4.7</text><text x="206" y="160" text-anchor="middle">да / нет</text></g><g class="theory-tree-node"><rect x="423" y="116" width="182" height="58" rx="12"/><text x="514" y="141" text-anchor="middle">Рейтинг ≤ 6.3</text><text x="514" y="160" text-anchor="middle">да / нет</text></g><g class="theory-leaf reject"><rect x="84" y="210" width="100" height="43" rx="12"/><text x="134" y="237" text-anchor="middle">отклонить</text></g><g class="theory-leaf approve"><rect x="228" y="210" width="100" height="43" rx="12"/><text x="278" y="237" text-anchor="middle">одобрить</text></g><g class="theory-leaf approve"><rect x="392" y="210" width="100" height="43" rx="12"/><text x="442" y="237" text-anchor="middle">одобрить</text></g><g class="theory-leaf reject"><rect x="536" y="210" width="100" height="43" rx="12"/><text x="586" y="237" text-anchor="middle">отклонить</text></g></svg><figcaption id="tree-visual-caption">Путь от корня к листу — интерпретируемое правило. Построение, однако, жадное: на каждом уровне оптимален только следующий вопрос.</figcaption></figure>`;
}

function svmVisual() {
  return `<figure class="theory-visual" aria-labelledby="svm-visual-caption"><svg viewBox="0 0 720 300" role="img" aria-label="Разделяющая гиперплоскость, зазор и опорные векторы SVM"><title>Геометрия SVM</title><path class="theory-grid" d="M60 38V246M60 246H674M60 90H674M60 142H674M60 194H674M183 38V246M306 38V246M429 38V246M552 38V246M674 38V246"/><path class="svm-theory-margin" d="M150 220L513 45M196 249L559 74"/><path class="svm-theory-boundary" d="M173 246L536 71"/><g class="theory-class-a"><circle cx="185" cy="199" r="9"/><circle cx="243" cy="211" r="9"/><circle cx="272" cy="164" r="9"/><circle cx="302" cy="185" r="9"/></g><g class="theory-class-b"><rect x="433" y="90" width="18" height="18" rx="3"/><rect x="489" y="103" width="18" height="18" rx="3"/><rect x="526" y="137" width="18" height="18" rx="3"/><rect x="554" y="88" width="18" height="18" rx="3"/></g><circle class="svm-theory-support" cx="302" cy="185" r="14"/><rect class="svm-theory-support" x="424" y="81" width="36" height="36" rx="8"/><text x="78" y="28">класс −1</text><text x="571" y="28">класс +1</text><text x="332" y="138">wᵀx+b=0</text><text x="472" y="183">зазор</text></svg><figcaption id="svm-visual-caption">Толстая линия — решающая граница. Две пунктирные — уровни y(wᵀx+b)=1. Обведённые объекты — опорные векторы.</figcaption></figure>`;
}

function logisticVisual() {
  return `<figure class="theory-visual" aria-labelledby="logistic-visual-caption"><svg viewBox="0 0 720 300" role="img" aria-label="Линейный score и сигмоида логистической регрессии"><title>Score до сигмоиды и вероятность после неё</title><path class="theory-grid" d="M54 38V244M54 244H330M54 90H330M54 142H330M54 194H330M123 38V244M192 38V244M261 38V244M390 244H674M390 90H674M390 142H674M390 194H674M390 38V244M461 38V244M532 38V244M603 38V244M674 38V244"/><path class="theory-axis" d="M54 244H330M54 244V30M390 244H674M390 244V30"/><path class="theory-curve" d="M82 220L302 58"/><path class="theory-descent" d="M472 230 C500 230 512 224 528 209 C546 191 555 171 570 142 C585 113 600 92 617 75 C634 59 649 54 663 53"/><circle class="theory-step" cx="570" cy="142" r="6"/><text x="65" y="28">до σ: z = wᵀx+b</text><text x="397" y="28">после σ: p = P(y=1|x)</text><text x="270" y="231">z=0</text><text x="651" y="231">z</text><text x="401" y="86">1</text><text x="401" y="232">0</text><text x="574" y="131">p=0.5</text></svg><figcaption id="logistic-visual-caption">Левая часть — линейный score, который может быть любым числом. Сигмоида переводит его в интервал (0, 1); граница z=0 становится порогом p=0.5.</figcaption></figure>`;
}

export const theoryPages = {
  logistic: {
    route: 'logistic', title: 'Логистическая<br><span>регрессия.</span>', label: 'алгоритм / полный разбор',
    lead: 'Логистическая регрессия строит линейный score, но не выдаёт его за вероятность: сначала пропускает через сигмоиду, затем обучает параметры log-loss’ом.',
    outline: [['logistic-intro', '01 / постановка'], ['logistic-score', '02 / score z'], ['logistic-sigmoid', '03 / сигмоида'], ['logistic-loss', '04 / log-loss'], ['logistic-gradient', '05 / градиент'], ['logistic-boundary', '06 / граница'], ['logistic-regularization', '07 / ridge'], ['logistic-threshold', '08 / порог и калибровка']],
    content: `${section('logistic-intro', '01 / постановка задачи', 'Классификация — не регрессия с округлением', `<p>Target здесь бинарный: «готов к сложному модулю» или «нужна доработка». Хотим оценить не произвольное число, а условную вероятность P(Y=1|X=x). Линейная регрессия может дать −0.4 или 1.3, что невозможно прочитать как вероятность; её MSE также симметрично относится к ошибкам, хотя уверенная неверная классификация должна наказываться особенно сильно.</p><p>Логистическая регрессия сохраняет ценное свойство линейной модели — прозрачный score из вкладов признаков — но меняет слой выхода и функцию потерь. Поэтому это не «линейная регрессия для классов», а вероятностная модель Бернулли.</p><div class="theory-callout"><b>Параметры и решение — разные вещи.</b> Модель выдаёт вероятность p. Правило «готов, если p≥0.5» — отдельный порог, который зависит от цены ложноположительных и ложноотрицательных ошибок.</div>`)}${section('logistic-score', '02 / линейный score', 'До сигмоиды всё ещё прямая', `<div class="formula">z(x) = w<sup>T</sup>x + b = w<sub>1</sub>x<sub>1</sub> + ··· + w<sub>d</sub>x<sub>d</sub> + b</div><p>z называют logit, score или линейным предиктором. Он живёт на всей числовой прямой: z=3 и z=−3 допустимы. Знак z задаёт сторону разделяющей гиперплоскости, а модуль говорит, насколько далеко объект по шкале текущей модели. На сцене модуля слева именно этот score: линия z=0 — граница до преобразования.</p><p>При увеличении x<sub>j</sub> на единицу log-odds меняется на w<sub>j</sub>. Это важно: сам эффект на вероятность не постоянен — у сигмоиды насыщаются хвосты. Сравнивать веса между признаками разумно только после сопоставимого масштабирования.</p>`)}${section('logistic-sigmoid', '03 / сигмоида', 'Как score становится вероятностью', `<div class="formula">σ(z) = 1 / (1 + e<sup>−z</sup>)<br>p(x) = P(Y=1|x) = σ(w<sup>T</sup>x+b)</div><p>Сигмоида монотонна: больший score даёт большую вероятность, но всегда 0&lt;p&lt;1. При z=0 получается p=0.5. Её обратная функция — logit: log(p/(1−p))=z. Отсюда линейность относится не к вероятности, а к логарифму отношения шансов.</p><p>В правой части сцены видно один и тот же score до и после σ. Малое изменение z возле нуля заметно меняет вероятность; в хвостах p уже близка к 0 или 1 и меняется медленнее. Это не ошибка алгоритма, а геометрия вероятностей.</p>${logisticVisual()}`)}${section('logistic-loss', '04 / log-loss', 'Почему уверенная ошибка дороже', `<div class="formula compact">L(y,p) = −[y log p + (1−y) log(1−p)]<br>J(w,b) = 1/n · ΣL(y<sub>i</sub>, p<sub>i</sub>)</div><p>Если y=1, остаётся −log p: предсказать p=0.99 почти бесплатно, а p=0.01 получает огромный штраф. Если y=0, работает −log(1−p). Это отрицательный log-likelihood независимых наблюдений Бернулли, поэтому минимизация BCE совпадает с поиском наиболее правдоподобных параметров модели.</p><p>Accuracy не заменяет log-loss: она видит только сторону порога. Прогнозы p=0.51 и p=0.99 одинаково «правильные» при пороге 0.5, но несут совершенно разную уверенность. Log-loss обучает именно вероятности, если модель и данные достаточно согласованы.</p>`)}${section('logistic-gradient', '05 / градиентный спуск', 'Почему производная такая простая', `<div class="formula compact">∂J/∂w<sub>j</sub> = 1/n · Σ(p<sub>i</sub>−y<sub>i</sub>)x<sub>ij</sub><br>∂J/∂b = 1/n · Σ(p<sub>i</sub>−y<sub>i</sub>)<br>w ← w − η∇J</div><p>Здесь происходит красивое сокращение: производная BCE по p и производная сигмоиды p(1−p) дают остаток p−y. Он похож на ошибку линейной регрессии, но p уже ограничена вероятностной шкалой. Один шаг в модуле действительно суммирует эти остатки по всем объектам.</p><p>Loss выпуклый по w и b для фиксированных признаков: локальных минимумов нет. Но плохой learning rate всё равно делает путь медленным или неустойчивым; масштабирование признаков улучшает обусловленность так же, как в линейной регрессии.</p>`)}${section('logistic-boundary', '06 / граница и odds', 'Линия до и после преобразования', `<div class="formula">z(x)=0 ⇔ p(x)=0.5<br>log[p(x)/(1−p(x))] = w<sup>T</sup>x+b</div><p>На плоскости двух признаков z=0 — прямая, а в большем числе измерений — гиперплоскость. Сигмоида не изгибает эту границу: она лишь превращает каждый уровень score в вероятность. Линии z=const и p=const — это те же параллельные гиперплоскости, только подписанные по-разному.</p><p>Поэтому логистическая регрессия хорошо работает, когда классы можно достаточно адекватно разделить линейной комбинацией признаков. Для изогнутой границы нужны преобразования признаков, базисные функции или другая модель; сама сигмоида не добавляет нелинейности по X.</p>`)}${section('logistic-regularization', '07 / L2 и разделимость', `<div class="formula">J<sub>λ</sub>(w,b) = J(w,b) + λ‖w‖²<sub>2</sub><br>∂J<sub>λ</sub>/∂w = ∂J/∂w + 2λw</div><p>На полностью разделимых данных без регуляризации веса могут бесконечно расти: всё более уверенный прогноз продолжает уменьшать log-loss, а конечного минимума нет. L2 делает большие веса дорогими, выбирает конечное решение и обычно улучшает перенос на новые объекты. Свободный член b часто не регуляризируют.</p><p>Регуляризацию и learning rate выбирают на validation. Нельзя делать вывод, что маленький weight означает «неважный» признак: коррелированные признаки делят вклад между собой.</p>`)}${section('logistic-threshold', '08 / порог, калибровка и честная проверка', `<p>Если p - корректная условная вероятность для целевой популяции, порог 0.5 оптимален при одинаковой цене ошибок; равенство долей классов не требуется. При цене C_FP за ложноположительное и C_FN за ложноотрицательное решение выбираем класс 1, когда C_FP(1-p) ≤ C_FN p, то есть p ≥ C_FP/(C_FP+C_FN). Если пропустить реально готового ученика дешевле, чем допустить неподготовленного, порог поднимают; если важнее не пропустить потенциально готового — опускают. Сравнивают такие решения по precision, recall, PR/ROC-кривым и ожидаемой цене, но выбирают их на validation, не на test.</p><p>Вероятность модели может быть некалибрована: среди объектов с p≈0.7 положительный класс не обязан встречаться в 70% случаев. Проверяют reliability diagram, Brier score и при необходимости калибруют модель на отдельной части данных. Высокая accuracy не доказывает калибровку.</p>${sources('Материалы для дальнейшего чтения', [reference('Яндекс Учебник — линейные модели', yandexLinearUrl), reference('Яндекс Учебник — вероятностный подход', yandexProbabilityUrl), reference('Курс лекций', courseUrl)])}`)} `
  },
  linear: createLinearTheory({ section, notationTable, derivationStack, equationCard }),
  knn: {
    route: 'knn', title: 'K ближайших<br><span>соседей.</span>', label: 'алгоритм / полный разбор',
    lead: 'KNN не выводит общую формулу зависимости. Он делает предсказание, опираясь на геометрию уже размеченных объектов — поэтому «близость» здесь важнее всего остального.',
    outline: [['knn-intro', '01 / постановка'], ['knn-distance', '02 / метрика'], ['knn-scaling', '03 / масштаб'], ['knn-vote', '04 / голосование'], ['knn-choice', '05 / k и веса'], ['knn-validation', '06 / настройка'], ['knn-complexity', '07 / размерность'], ['knn-limits', '08 / границы']],
    content: `${section('knn-intro', '01 / постановка задачи', 'Локальная гипотеза вместо обучения весов', `<p>В KNN train-выборка сама является моделью. Для нового объекта z мы вычисляем расстояние до всех известных объектов, берём k ближайших и выводим ответ из их target. В классификации это голосование; в регрессии — среднее или взвешенное среднее ответов соседей.</p><p>Это lazy learning: дорогой этап перенесён с обучения на предсказание. Сильная сторона — объяснимость одного решения: можно показать конкретные строки, расстояния и их голоса. Слабая — локальная интуиция верна, только если пространство признаков действительно имеет смысловую геометрию.</p>${knnVisual()}`)}${section('knn-distance', '02 / метрика', 'Что значит «похожи»', `<div class="formula compact">d<sub>2</sub>(x,z) = √Σ<sub>j</sub>(x<sub>j</sub> − z<sub>j</sub>)² &nbsp; — евклидова<br>d<sub>1</sub>(x,z) = Σ<sub>j</sub>|x<sub>j</sub> − z<sub>j</sub>| &nbsp; — манхэттенская<br>d<sub>p</sub>(x,z) = (Σ<sub>j</sub>|x<sub>j</sub> − z<sub>j</sub>|<sup>p</sup>)<sup>1/p</sup></div><p>Метрика должна быть неотрицательной, симметричной, равной нулю на одинаковых объектах и удовлетворять неравенству треугольника. Евклидова d<sub>2</sub> измеряет прямой путь, манхэттенская d<sub>1</sub> — сумму отклонений по осям. Для категорий нельзя подставлять произвольные числовые коды: нужна мера вроде Hamming distance или доменная функция сходства.</p><p>Выбор метрики — часть модели. Если «схожесть» не совпадает со структурой задачи, даже идеально реализованный KNN выберет бессмысленных соседей.</p>`)}${section('knn-scaling', '03 / единицы измерения', 'Почему один крупный признак ломает соседство', `<div class="formula">x'<sub>j</sub> = (x<sub>j</sub> − μ<sub>j</sub>) / σ<sub>j</sub></div><p>Расстояние складывает координаты. Если время измеряется в минутах, а сложность — по шкале 0–10, разброс времени может полностью заглушить сложность. Стандартизация приводит числовые признаки примерно к нулевому среднему и единичной дисперсии. Альтернатива — robust scaling через медиану и IQR, полезный при выбросах.</p><p>μ и σ вычисляются только на train. Затем <em>те же</em> параметры применяются к validation, test и production. Если нормировать каждую часть отдельно, модель сравнивает объекты в разных системах координат и получает утечку информации.</p><div class="theory-callout"><b>В интерактивном примере:</b> признаки намеренно показаны в исходных шкалах. Это позволяет увидеть, как «Время решения, мин» может влиять на выбор соседей сильнее «Сложности задачи».</div>`)}${section('knn-vote', '04 / из соседей в ответ', `<div class="formula">ĉ(z) = arg max<sub>c</sub> Σ<sub>i ∈ N<sub>k</sub>(z)</sub> 𝟙[y<sub>i</sub>=c]<br>ŷ(z) = 1/k · Σ<sub>i ∈ N<sub>k</sub>(z)</sub> y<sub>i</sub> &nbsp; (регрессия)</div><p>N<sub>k</sub>(z) — индексы k ближайших объектов. Невзвешенное голосование даёт одинаковое право самому близкому и k-му соседу. Взвешенное голосование заменяет единицу на a(d<sub>i</sub>), например 1/(d<sub>i</sub>+ε): близкий объект влияет сильнее, но возрастает чувствительность к шумной точке почти в нуле.</p><p>При чётном k в бинарной задаче возможна ничья. Её нельзя «спрятать»: нужно заранее определить правило, например выбрать класс с большим prior или меньшим средним расстоянием. Доли голосов не следует без проверки выдавать за калиброванные вероятности.</p>`)}${section('knn-choice', '05 / k, bias и variance', 'Сглаживание не равно улучшению', `<p>k = 1 копирует локальный шум и имеет низкий bias, но высокий variance: маленькое изменение train-выборки меняет границу. Большой k усредняет большую область: variance падает, зато повышается bias и может исчезнуть редкий, но настоящий локальный класс. Это классический bias–variance trade-off.</p><p>Размер k должен зависеть от объёма данных и плотности, а не быть «магическим числом». Радиусные соседи иногда естественнее: вместо фиксированного количества брать всех в радиусе r, но тогда в разреженной области соседей может не оказаться.</p>`)}${section('knn-validation', '06 / настройка без самообмана', `<p>Метрику, масштабирование, k, схему весов и набор признаков выбирают на validation или внутри кросс-валидации. Подбирать k по train accuracy бессмысленно: k=1 почти всегда выглядит слишком хорошо, потому что объект является собственным ближайшим соседом.</p><p>В дисбалансной задаче accuracy может скрыть провал редкого класса. Смотри на precision, recall, F1, PR-AUC или стоимость ошибок домена. Если классы неравновероятны, вес класса в голосовании может быть разумной модификацией — но её тоже валидируют.</p>`)}${section('knn-complexity', '07 / вычисления и высокая размерность', `<div class="formula">обучение: O(1) &nbsp; | &nbsp; память: O(nd) &nbsp; | &nbsp; один запрос: O(nd) + отбор k</div><p>Наивный KNN сравнивает запрос с n строками; для поиска только k лучших достаточно частичного отбора, а не полной сортировки. KD-tree и ball tree могут ускорять поиск в малой размерности. В высокой размерности их преимущество часто исчезает: пространства становятся слишком разреженными, и структуры индекса возвращаются почти к полному перебору.</p><p>При росте d отношение расстояния до ближайшего и дальнего объекта стремится к единице: понятие «локальный сосед» теряет контраст. Здесь важнее хорошие признаки, снижение размерности или другой тип модели, чем подбор ещё одного значения k.</p>`)}${section('knn-limits', '08 / когда KNN применять уместно', `<p>KNN полезен на небольших и средних данных, где признаки имеют ясную метрику: геолокация, visual embedding’и, поиск похожих кейсов. Он плохо подходит, когда train очень велик, признаки шумные/разномасштабные, важны быстрые предсказания или закономерность глобальна, а не локальна.</p><p>Отсутствие явной фазы обучения не означает отсутствия моделирования. В KNN моделью становятся выбор пространства признаков, преобразование данных, метрика и правило голосования — именно там лежит основная интеллектуальная работа.</p>${sources('Материалы для продолжения', [reference('Яндекс Учебник — метрические методы', yandexMetricUrl), reference('Яндекс Учебник — подбор гиперпараметров', yandexTuningUrl), reference('Плейлист «Машинное обучение 1»', courseUrl)])}`)}
    `
  },
  tree: {
    route: 'tree', title: 'Решающее<br><span>дерево.</span>', label: 'алгоритм / полный разбор',
    lead: 'Решающее дерево строит программу из вопросов о признаках. Оно интуитивно прозрачно, но нуждается в особенно аккуратной проверке: один жадный split наверху меняет всё поддерево.',
    outline: [['tree-intro', '01 / модель'], ['tree-predicates', '02 / split'], ['tree-impurity', '03 / impurity'], ['tree-split', '04 / поиск'], ['tree-regression', '05 / регрессия'], ['tree-control', '06 / сложность'], ['tree-missing', '07 / пропуски'], ['tree-importance', '08 / важность'], ['tree-limits', '09 / границы']],
    content: `${section('tree-intro', '01 / модель', 'Дерево — это кусочно-постоянная функция', `<p>Внутренний узел задаёт вопрос, ребро выбирает ответ, лист возвращает прогноз. Для классификации лист обычно хранит большинство класса и его долю; для регрессии — среднее target в этом листе. Путь от корня до листа можно прочесть как правило if/else — это главное объяснительное преимущество дерева.</p><p>В пространстве числовых признаков каждое ветвление режет область осевым порогом, а листья складываются в прямоугольники. Поэтому дерево естественно выражает взаимодействия и нелинейные границы: например, «доход высокий <em>и</em> рейтинг низкий».</p>${treeVisual()}`)}${section('tree-predicates', '02 / предикаты', 'Какие вопросы можно задать', `<div class="formula">x<sub>j</sub> ≤ t &nbsp; ? &nbsp; S<sub>L</sub> : S<sub>R</sub></div><p>Для числового признака CART использует бинарный порог. После сортировки уникальных значений достаточно проверять границы между соседними значениями: внутри промежутка состав левой и правой групп не меняется. Для категории возможны тест «принадлежит ли множеству A» или разбиение по отдельным значениям; при большом числе категорий такие split’ы легко переобучаются.</p><p>В интерактивном дереве клик по круглой вершине показывает фактический предикат, число объектов в узле, impurity и ΔI. Это не декоративная подпись: именно этот вопрос разделил точки на графике.</p>`)}${section('tree-impurity', '03 / неоднородность', 'Gini и entropy измеряют, насколько смешан узел', `<div class="formula compact">Gini(S) = 1 − Σ<sub>c</sub>p<sub>c</sub>²<br>H(S) = −Σ<sub>c</sub>p<sub>c</sub>log<sub>2</sub>p<sub>c</sub></div><p>p<sub>c</sub> — доля класса c в узле S. В чистом листе одна доля равна единице, поэтому Gini и entropy равны нулю. Для двух классов максимумы достигаются при 50/50: Gini = 0.5, entropy = 1 бит. Энтропия имеет информационно-теоретическую интерпретацию ожидаемой неопределённости, а Gini удобен вычислительно; на практике они часто выбирают похожие split’ы.</p><div class="impurity-compare"><div><span>почти чистый узел</span><b>90% / 10%</b><i>Gini = 0.18</i></div><div><span>максимально смешанный</span><b>50% / 50%</b><i>Gini = 0.50</i></div></div><p>При split важна взвешенная смесь потомков: один маленький идеально чистый лист не оправдывает ухудшение большого.</p>`)}${section('tree-split', '04 / поиск лучшего вопроса', `<div class="formula">ΔI = I(S) − |S<sub>L</sub>|/|S|·I(S<sub>L</sub>) − |S<sub>R</sub>|/|S|·I(S<sub>R</sub>)</div><p>Алгоритм перебирает допустимые feature/threshold, отбрасывает split’ы с слишком маленькими листьями, считает взвешенную impurity потомков и берёт максимальное ΔI. Затем повторяет то же в каждом дочернем узле. Это top-down greedy induction: лучшая ближайшая развилка не обязана давать глобально лучшее дерево, но полный перебор всех деревьев неосуществим.</p><p>Для несбалансированных классов или различной цены ошибок можно использовать class weights, альтернативные критерии или менять решение в листе. Сначала нужно зафиксировать, какую метрику качества оптимизирует продукт: gain сам по себе не заменяет цель.</p>`)}${section('tree-regression', '05 / дерево для числового target', 'Та же структура, другая ошибка', `<div class="formula">I(S) = 1/|S| · Σ<sub>i∈S</sub>(y<sub>i</sub> − ȳ<sub>S</sub>)²</div><p>В regression tree лист предсказывает среднее ȳ<sub>S</sub>, потому что оно минимизирует сумму квадратов внутри листа. Split выбирают по уменьшению взвешенной дисперсии или SSE. Получается ступенчатая функция: она ловит нелинейности и взаимодействия, но не умеет естественно экстраполировать за диапазон train-значений.</p><p>Это важно отличать от линейной регрессии: линейная модель может продолжить прямую за наблюдаемый интервал, что тоже не всегда разумно; дерево вне виденных областей фактически повторяет значение крайнего листа.</p>`)}${section('tree-control', '06 / переобучение и pruning', `<p>Глубокое дерево способно выучить train почти идеально, разделяя данные до единичных листьев. Это низкий bias и огромный variance. Ограничения max depth, min samples split и min samples leaf — pre-pruning: они останавливают рост раньше. Их сравнивают на validation или nested cross-validation.</p><p>Post-pruning строит более крупное дерево, а затем удаляет ветви, если их вклад в validation недостаточен. Cost-complexity pruning добавляет штраф за число листьев: R(T)+α|T|. Искать глубину по test — та же утечка, что и подбирать learning rate по test.</p>`)}${section('tree-missing', '07 / пропуски', 'NaN должен быть частью обученного правила', `<p>У дерева нет единого «автоматически правильного» поведения с пропуском. Стратегию выбирает библиотека; она должна выучиться только на train и так же сработать при validation и в production.</p><div class="missing-grid"><article><b>Направление по умолчанию</b><span>При поиске split’а пробуют отправить NaN влево и вправо; сохраняют направление с лучшим gain. При предсказании пропуск повторяет это правило.</span></article><article><b>Surrogate split</b><span>Подбирают запасной предикат по другому признаку, который лучше всего воспроизводит основное ветвление. Если главный признак пропущен, работает surrogate.</span></article><article><b>Отдельное значение</b><span>Для категории «unknown» может быть самостоятельным значением. Это уместно, если сам факт пропуска несёт сигнал.</span></article></div><p>Импутация медианой/модой возможна, но меняет данные и может скрыть информативность пропуска. Её параметры также считаются на train. В текущем примере пропусков нет намеренно: сначала видна чистая механика split’а.</p>`)}${section('tree-importance', '08 / как не переинтерпретировать дерево', `<p>Сумма взвешенных уменьшений impurity по split’ам признака часто называется feature importance. Это быстро, но смещено в пользу непрерывных признаков и категорий с большим числом уникальных значений, а коррелированные признаки делят важность непредсказуемо. Высокая importance не доказывает причинный эффект.</p><p>Permutation importance честнее привязана к выбранной метрике: на validation перемешивают один признак и измеряют падение качества. Она тоже ломается при сильно коррелированных признаках, потому что модель может заменить один другим. Объяснение конкретного решения — путь в дереве; объяснение влияния признака в целом требует отдельного анализа.</p>`)}${section('tree-limits', '09 / применимость', `<p>Дерево не требует масштабирования, обрабатывает нелинейности и смешанные признаки, быстро объясняет отдельный прогноз. Но одиночное дерево неустойчиво: небольшое изменение данных может сменить верхний split и всё поддерево. Ансамбли уменьшают variance: random forest усредняет много декоррелированных деревьев, а boosting последовательно исправляет ошибки слабых деревьев.</p><p>В учебнике одиночное дерево важно потому, что все эти ансамбли наследуют его базовый механизм: кандидаты split’ов, impurity, ограничения сложности и честная validation.</p>${sources('Материалы для продолжения', [reference('Яндекс Учебник — решающие деревья', yandexTreeUrl), reference('ВШЭ: решающие деревья', treeLectureUrl), reference('ВШЭ: леса и градиентный бустинг', 'https://www.youtube.com/watch?v=pXFZsXlVM-M'), reference('Плейлист «Машинное обучение 1»', courseUrl)])}`)}
    `
  },
  svm: {
    route: 'svm', title: 'Метод опорных<br><span>векторов.</span>', label: 'алгоритм / полный разбор',
    lead: 'SVM строит разделяющую гиперплоскость не просто между классами, а с максимально широким зазором. В решении особенно важны объекты около границы — опорные векторы.',
    outline: [['svm-intro', '01 / геометрия'], ['svm-hard-margin', '02 / hard margin'], ['svm-dual', '03 / dual и KKT'], ['svm-support', '04 / опорные'], ['svm-hinge', '05 / hinge loss'], ['svm-soft-margin', '06 / параметр C'], ['svm-optimization', '07 / оптимизация'], ['svm-kernels', '08 / ядра'], ['svm-practice', '09 / практика'], ['svm-limits', '10 / границы']],
    content: `${section('svm-intro', '01 / геометрическая постановка', 'Классификатор как ориентированная граница', `<p>Пусть y<sub>i</sub> ∈ {−1,+1}. Линейный классификатор вычисляет score f(x)=w<sup>T</sup>x+b и выбирает знак: ŷ=sign(f(x)). Уравнение f(x)=0 задаёт гиперплоскость. В двумерной визуализации это прямая; в трёх измерениях — плоскость; дальше визуально её уже не нарисовать, но математика та же.</p><p>Таких разделяющих прямых может быть много. SVM предпочитает не любую, а ту, у которой ближайшие объекты обоих классов лежат как можно дальше от границы. Большой зазор делает решение менее чувствительным к небольшому шуму во входе.</p>${svmVisual()}`)}${section('svm-hard-margin', '02 / максимальный зазор', 'От расстояния до задачи оптимизации', `<p>Расстояние от точки x до гиперплоскости w<sup>T</sup>x+b=0 равно |w<sup>T</sup>x+b|/‖w‖. Масштаб (w,b) не определён: (2w,2b) задают ту же границу. SVM фиксирует его условиями y<sub>i</sub>(w<sup>T</sup>x<sub>i</sub>+b) ≥ 1. Тогда ближайшие допустимые уровни — f(x)=±1, а ширина всей полосы равна 2/‖w‖.</p><div class="formula">min<sub>w,b</sub> 1/2‖w‖² &nbsp; при &nbsp; y<sub>i</sub>(wᵀx<sub>i</sub>+b) ≥ 1, ∀i</div><p>Минимизировать норму w — то же, что максимизировать зазор. Это convex quadratic program. Hard-margin SVM ломается при одном ошибочно размеченном или пересекающемся объекте: допустимого решения может не существовать.</p>`)}${section('svm-dual', '03 / двойственная задача и KKT', 'Почему в решении остаются не все объекты', `<p>Введём множители Лагранжа α<sub>i</sub> ≥ 0 для ограничений. Стационарность лагранжиана даёт w=Σα<sub>i</sub>y<sub>i</sub>x<sub>i</sub> и Σα<sub>i</sub>y<sub>i</sub>=0. Подстановка убирает w и b:</p><div class="formula compact">max<sub>α</sub> Σα<sub>i</sub> − 1/2ΣΣα<sub>i</sub>α<sub>j</sub>y<sub>i</sub>y<sub>j</sub>x<sub>i</sub>ᵀx<sub>j</sub><br>при α<sub>i</sub>≥0, &nbsp; Σα<sub>i</sub>y<sub>i</sub>=0</div><p>Условие комплементарной нежёсткости α<sub>i</sub>[y<sub>i</sub>f(x<sub>i</sub>)−1]=0 означает: если объект далеко за полосой, его α<sub>i</sub>=0 и он не влияет на w. Если α<sub>i</sub>&gt;0, объект лежит на границе или нарушает её — это опорный вектор.</p><p>Двойственная форма важна: в ней данные встречаются только как скалярные произведения x<sub>i</sub><sup>T</sup>x<sub>j</sub>. Это открывает ядровой трюк.</p>`)}${section('svm-support', '04 / опорные векторы', 'Не все train-строки одинаково важны', `<div class="formula">w = Σ<sub>i∈SV</sub> α<sub>i</sub>y<sub>i</sub>x<sub>i</sub></div><p>В hard-margin случае точки строго вне зазора можно немного сдвинуть, и граница не изменится. В soft-margin опорными также становятся точки внутри полосы и ошибочно классифицированные объекты. В живой лаборатории обводка отмечает точки с положительным αᵢ с учётом численного допуска. В пошаговой демонстрации выделение показывает объекты на краю или внутри зазора по текущим весам.</p><p>Это не значит, что SVM «видит только их» с самого начала. При обучении алгоритм использует все строки, но оптимум становится разреженным. Много опорных векторов может означать шум, слабую разделимость или слишком агрессивное C.</p>`)}${section('svm-hinge', '05 / soft margin как loss', `<div class="formula">ℓ<sub>hinge</sub>(y,f(x)) = max(0, 1 − y·f(x))</div><p>Если y·f(x) ≥ 1, объект правильно классифицирован и находится не ближе границы, чем зазор: loss нулевой. Если 0 &lt; y·f(x) &lt; 1, знак верный, но объект в полосе. Если y·f(x) &lt; 0, класс неверный. При нулевом отступе точка лежит на границе. Hinge loss не просто требует правильный класс — он требует уверенности с запасом.</p><p>В точке y·f(x)=1 у функции излом: обычной производной нет, но существует субградиент. В режиме «Один шаг» используется именно он. Обновление складывается из регуляризирующего члена w и вклада только объектов с y·f(x)&lt;1.</p>${svmHingeExplorer}`)}${section('svm-soft-margin', '06 / параметр C', `<div class="formula">min<sub>w,b</sub> 1/2‖w‖² + C · 1/n Σmax(0, 1 − y<sub>i</sub>(wᵀx<sub>i</sub>+b))</div><p>Малый C сильнее ценит широкий зазор и допускает больше нарушений: больше регуляризации, больше bias, меньше variance. Большой C агрессивнее исправляет train-нарушения, сужает зазор и может переобучиться на выбросы. Нормировка на n делает смысл C сопоставимее при изменении размера выборки; разные библиотеки могут использовать другую конвенцию.</p><p>Универсально «правильного» C нет. Его выбирают через cross-validation вместе с масштабированием и типом ядра. Настраивать C по accuracy на train — прямой путь к переобучению.</p>`)}${section('svm-optimization', '07 / как обучается SVM', `<p>Классические линейные SVM часто решают dual-задачу методом SMO или специализированными quadratic-programming алгоритмами. Для большой линейной задачи удобно оптимизировать primal: subgradient descent, Pegasos, coordinate descent или LIBLINEAR-подобные методы. В пошаговом линейном режиме используется полный субградиент soft-margin objective, поэтому каждый «Один шаг» наблюдаем и сопоставим с формулой.</p><div class="formula compact">∇<sub>w</sub>J = w − C/n·Σ<sub>yᵢf(xᵢ)&lt;1</sub>y<sub>i</sub>x<sub>i</sub><br>∂J/∂b = −C/n·Σ<sub>yᵢf(xᵢ)&lt;1</sub>y<sub>i</sub></div><p>Learning rate влияет на скорость и устойчивость субградиентного спуска. В отличие от гладкой MSE hinge loss имеет излом, поэтому schedule learning rate и критерий остановки особенно важны. Число итераций без графика objective — не доказательство сходимости.</p>`)}${section('svm-kernels', '08 / ядровой трюк', 'Нелинейность без явного перечисления признаков', `<div class="formula compact">K(x,z) = φ(x)ᵀφ(z)<br>f(x) = Σ<sub>i∈SV</sub>α<sub>i</sub>y<sub>i</sub>K(x<sub>i</sub>,x) + b</div><p>Если заменить скалярное произведение в dual-задаче ядром K, SVM словно строит линейную границу в пространстве признаков φ(x), не вычисляя φ явно. Полиномиальное ядро K=(γx<sup>T</sup>z+r)<sup>p</sup> добавляет взаимодействия; RBF K=exp(−γ‖x−z‖²) создаёт локальное сходство и может рисовать гибкие границы.</p><p>Ядро должно быть положительно полуопределённым, иначе задача может потерять выпуклость. γ в RBF задаёт радиус влияния: большой γ делает область каждой точки узкой и повышает риск переобучения. Ядровый SVM тяжело масштабируется по числу объектов, поэтому на больших данных часто выбирают linear SVM или приближения.</p>`)}${section('svm-practice', '09 / pipeline и оценка', `<p>SVM чувствителен к масштабу: в w<sup>T</sup>x евклидова геометрия напрямую определяет и границу, и ядро. Числовые признаки стандартизируют в pipeline, обученном на train. Категории кодируют осмысленно; один hot-encoded признак с тысячами редких значений требует осторожности.</p><p>Базовый SVC отдаёт signed distance или decision function, но это не вероятность. Если нужна вероятность для порога, ранжирования или ожидаемой стоимости, её калибруют на отдельной валидационной процедуре (Platt scaling/isotonic). Для многоклассовой задачи используют one-vs-rest или one-vs-one; это набор бинарных SVM.</p>`)}${section('svm-limits', '10 / где SVM силён и где нет', `<p>Linear SVM хорош в высокоразмерных разреженных признаках, например текстовых bag-of-words/TF-IDF, где зазор полезен, а линейное обучение масштабируется. Ядровый SVM хорош на умеренных данных со сложной, но геометрически осмысленной границей.</p><p>Он не заменяет анализ данных: плохо переносит сильный дисбаланс без class weights, чувствителен к масштабу и шумным меткам, требует настройки C и параметров ядра, а ядровая версия трудно масштабируется. В реальном проекте сравни SVM с baseline-моделью, деревьями/бустингом и проверяй метрики на независимых данных.</p>${sources('Материалы для продолжения', [reference('Яндекс Учебник — SVM и ядровой трюк', yandexSvmUrl), reference('Яндекс Учебник — подбор гиперпараметров', yandexTuningUrl), reference('Плейлист «Машинное обучение 1»', courseUrl)])}`)}
    `
  }
};

// Основные разделы объясняют механику алгоритма. Эти продолжения связывают её
// с вероятностной моделью, обобщением и границами причинной интерпретации.
// Они опираются на русскоязычные главы Яндекс Учебника, перечисленные внизу
// каждой страницы; каузальная часть специально отделена от предсказательной.
const deepTheory = {
  knn: {
    outline: [
      ['knn-probability', '09 / локальная вероятность'],
      ['knn-generalization', '10 / обобщение'],
      ['knn-shift', '11 / сдвиг данных'],
      ['knn-causality', '12 / причинность']
    ],
    content: `${section('knn-probability', '09 / локальная вероятность', 'Голосование как оценка условного распределения', `<p>Для классификации KNN можно читать не как «большинство соседей», а как локальную оценку условной вероятности. Если N<sub>k</sub>(z) — k ближайших к z объектов, то доля класса c в этой окрестности оценивает P(Y=c|X=z).</p><div class="formula">p̂(Y=c|X=z) = 1/k · Σ<sub>i∈Nₖ(z)</sub>𝟙[y<sub>i</sub>=c], &nbsp; ŷ(z)=argmax<sub>c</sub> p̂(Y=c|X=z)</div><p>Эта оценка имеет смысл, только если маленький шар вокруг z содержит объекты, похожие не по названию признаков, а по механизму формирования target. В регрессии вместо индикатора стоит y<sub>i</sub>: локальное среднее оценивает E[Y|X=z]. Взвешивание 1/(d+ε) снижает влияние дальних соседей, но увеличивает чувствительность к почти совпадающим и шумным точкам.</p>`)}` +
      `${section('knn-generalization', '10 / асимптотика и curse of dimensionality', 'Почему k нельзя выбирать один раз навсегда', `<p>Для согласованности KNN при росте n выбирают последовательность k<sub>n</sub>: k<sub>n</sub> → ∞, но k<sub>n</sub>/n → 0. Первое условие усредняет шум, второе удерживает радиус окрестности локальным. Это теоретический баланс bias и variance: фиксированное k остаётся шумным, а k, пропорциональное n, усредняет уже весь мир.</p><p>В d измерениях объём шара растёт как r<sup>d</sup>. Чтобы удержать достаточно соседей, радиус r должен расширяться, и «локальный» метод становится нелокальным. Добавить десять слабых признаков — не безобидная операция: они меняют ранжирование расстояний. Поэтому отбор признаков, доменная метрика и нормировка для KNN — часть статистической гипотезы, а не предварительная уборка данных.</p><p><a class="theory-inline-reference" href="${yandexMetricUrl}" target="_blank" rel="noreferrer">Яндекс Учебник о метрических методах ↗</a> разбирает эту геометрию и практические варианты метрик.</p>`)}` +
      `${section('knn-shift', '11 / сдвиг распределения', 'Чего не видно в таблице расстояний', `<p>KNN умеет интерполировать внутри области, покрытой train-объектами. Для точки вне этой области он всё равно вернёт «ближайших», но это не значит, что они достаточно похожи. Полезно отдельно хранить расстояние до k-го соседа или локальную плотность: большое значение — сигнал OOD, а не уверенного предсказания.</p><p>При covariate shift меняется P(X), при concept shift меняется P(Y|X). В первом случае старые соседи могут остаться условно полезными лишь после осторожной поправки на плотность; во втором даже точная прежняя геометрия устаревает. Validation, случайно перемешанный с прошлым train, не проверяет этот сценарий — нужен временной или доменный split.</p>`)}` +
      `${section('knn-causality', '12 / похожесть не равна эффекту', 'Почему matching требует больше, чем расстояние', `<p>Интуиция matching похожа на KNN: сравнить обработанный объект с похожими необработанными. Но каузальный вопрос требует потенциальных исходов и идентификации, а не только близости. Необходимы измеренные до воздействия конфаундеры Z, conditional exchangeability и overlap: у каждого профиля Z должны существовать реальные сравнимые объекты обеих групп.</p><div class="formula compact">E[Y(1)−Y(0)] = E<sub>Z</sub>[E[Y|T=1,Z] − E[Y|T=0,Z]]<br>только если (Y(0),Y(1)) ⫫ T | Z и есть перекрытие</div><p>Плохая шкала расстояния, пропущенный конфаундер, коллайдер или сосед «слишком далеко» делают matching смещённым. KNN может быть одним из оценщиков в каузальном pipeline, но не превращает наблюдательные данные в эксперимент.</p>`)}`
  },
  tree: {
    outline: [
      ['tree-probability', '10 / вероятности в листе'],
      ['tree-selection', '11 / поиск split’а'],
      ['tree-generalization', '12 / обобщение'],
      ['tree-causality', '13 / причинность']
    ],
    content: `${section('tree-probability', '10 / вероятности в листе', 'Что означает «вероятность» одиночного дерева', `<p>В классификационном листе дерево обычно отдаёт долю класса: p̂<sub>c</sub> = n<sub>c</sub>/n<sub>leaf</sub>. Это эмпирическая частота среди train-объектов, дошедших до листа, а не автоматически откалиброванная вероятность будущего события. Лист из двух объектов с долей 1.0 несёт намного меньше информации, чем лист из двухсот.</p><div class="formula">p̃<sub>c</sub> = (n<sub>c</sub> + α) / (n<sub>leaf</sub> + Kα)</div><p>Сглаживание Лапласа (α&gt;0, K классов) оттягивает экстремальные доли маленьких листьев к равномерному prior. Более фундаментальное решение — ограничить минимальный размер листа, использовать pruning и калибровать вероятности на отдельной выборке. Критерий Gini выбирает split, но не доказывает калибровку его листовых частот.</p>`)}` +
      `${section('tree-selection', '11 / поиск split’а', 'Максимальный gain завышает случайный сигнал', `<p>На каждом узле алгоритм перебирает много признаков и порогов и берёт максимум уменьшения impurity. Даже если все признаки независимы от target, максимум среди большого числа случайных флуктуаций обычно положителен. Непрерывные признаки и категории с большим числом уникальных значений получают больше попыток «случайно повезти».</p><div class="formula compact">ΔI(s) = I(S) − |S<sub>L</sub>|/|S|·I(S<sub>L</sub>) − |S<sub>R</sub>|/|S|·I(S<sub>R</sub>)<br>выбирается max<sub>s ∈ кандидаты</sub> ΔI(s), а не истинный причинный вклад признака</div><p>min_samples_leaf, max_depth и pruning уменьшают пространство кандидатов. Честный validation отвечает на вопрос, переносится ли выигрыш за пределы узла, на котором он найден. На малых данных особенно полезно повторять оценку на folds: один удачный split не становится законом природы.</p>`)}` +
      `${section('tree-generalization', '12 / сложность и variance', 'Почему дерево может помнить выборку', `<p>Дерево глубины d может создать до 2<sup>d</sup> листьев и, при достаточной глубине, почти изолировать отдельные объекты. В этом смысле у класса глубоких деревьев высокая ёмкость: эмпирический риск легко сделать малым, но разрыв с истинным риском может стать большим.</p><p>Ограничение глубины — это не эстетика картинки. Оно уменьшает число возможных разбиений и stabilizes прогноз: маленькое изменение train-строк реже переворачивает верхний split. Bagging и random forest используют именно нестабильность дерева: усреднение многих деревьев снижает variance, не требуя от одного дерева быть «истинным».</p><p>Проверка обобщения должна совпадать с будущим применением: случайный split для независимых клиентов, временной split для событий во времени, групповой split, если один пользователь оставляет много строк.</p>`)}` +
      `${section('tree-causality', '13 / predictive tree ≠ causal tree', 'Impurity отвечает не на тот вопрос', `<p>Обычное дерево ищет предикаты, лучше предсказывающие Y. Если признак T — лечение, высокий gain при split по T означает, что группы различаются по наблюдаемому Y. Причиной различия могут быть отбор, конфаундеры и разные исходные профили; impurity не различает эти сценарии.</p><p>Каузальные деревья ставят другую цель: найти неоднородность эффекта τ(x)=E[Y(1)−Y(0)|X=x]. Им нужны те же предположения идентификации — корректно измеренные до-treatment конфаундеры, overlap и независимое или условно независимое назначение T. Часто применяют sample splitting: на одной части выбирают разбиения, на другой оценивают эффект, чтобы не принять шум за сегмент с эффектом.</p><p>Поэтому путь в дереве — хорошее объяснение <em>предсказания</em>. Он не является доказательством того, что изменение указанного признака вызовет изменение target.</p>`)}`
  },
  svm: {
    outline: [
      ['svm-convexity', '11 / выпуклость'],
      ['svm-generalization', '12 / margin и риск'],
      ['svm-calibration', '13 / score и вероятность'],
      ['svm-causality', '14 / причинность']
    ],
    content: `${section('svm-convexity', '11 / выпуклая задача', 'Что гарантирует оптимизация — и чего не гарантирует', `<p>Primal soft-margin SVM складывает выпуклую квадратичную норму и выпуклую hinge loss. Поэтому любой локальный минимум является глобальным. Это сильнее, чем удобство реализации: при точном решении мы знаем, что не застряли в «плохой долине», как это может случиться в невыпуклой модели.</p><div class="formula compact">J(w,b) = 1/2‖w‖² + C/n Σmax(0,1−y<sub>i</sub>(wᵀx<sub>i</sub>+b))<br>0 ∈ ∂J(w,b) &nbsp; — условие оптимума для субградиента</div><p>В dual-форме сильная двойственность выполняется при обычных условиях выпуклой оптимизации с допустимой точкой; KKT связывают primal, dual и опорные векторы. Но выпуклость ничего не говорит о качестве на новых данных, о корректности меток или о том, что линейная граница соответствует механизму задачи. Это гарантия вычисления, а не гарантия смысла.</p>`)}` +
      `${section('svm-generalization', '12 / margin и обобщение', 'Широкий зазор — контролируемая сложность', `<p>При ограниченных признаках ‖x‖≤R ограничение нормы ‖w‖≤B сдерживает способность линейного класса подгонять произвольные метки. На высоком уровне его Rademacher-сложность масштабируется как RB/√n. Поскольку геометрический margin γ связан с 1/‖w‖, широкий зазор соответствует меньшей сложности класса при той же нормировке данных.</p><div class="formula compact">истинный риск ≲ эмпирический margin-risk + O(R‖w‖/√n)<br>ширина зазора = 2/‖w‖, но только после фиксирования масштаба X</div><p>Это не универсальная формула точности и не повод игнорировать validation. Граница применима при конкретных предположениях, а нормировка X меняет и R, и margin. Смысл SVM в том, что он явно выбирает компромисс между нарушениями train и контролем сложности, а не в магическом свойстве «самого большого зазора».</p><p>Общий язык риска и сложности изложен в <a class="theory-inline-reference" href="${yandexGeneralizationUrl}" target="_blank" rel="noreferrer">главе Яндекс Учебника об обобщении ↗</a>.</p>`)}` +
      `${section('svm-calibration', '13 / score не равен вероятности', 'Почему sign(f) недостаточен для решения с ценой ошибки', `<p>Значение f(x)=w<sup>T</sup>x+b — расстояние с масштабом ‖w‖, а не P(Y=1|X=x). Два SVM со схожими решениями могут иметь совершенно разные шкалы score, особенно после изменения C, доли классов или нормировки. Поэтому нельзя читать «f=2» как «вероятность 0.88».</p><div class="formula compact">p̂(Y=1|x) = 1 / (1 + exp(Af(x)+B))</div><p>Platt scaling обучает A и B на независимой calibration-выборке или внутри CV. Isotonic regression гибче, но требует больше данных. И калибровка, и порог решения должны быть выбраны без доступа к финальному test; иначе красивая вероятность окажется ещё одной подстройкой под прошлое.</p>`)}` +
      `${section('svm-causality', '14 / граница не отвечает «что будет, если»', 'Классификация и вмешательство — разные задачи', `<p>SVM оценивает правило для наблюдаемой связи между X и меткой Y. Даже если один признак сильно сдвигает score, из этого не следует, что вмешательство в признак изменит исход. Score построен для разделения классов, а не для оценки E[Y|do(X=x)].</p><p>Каузальный эффект требует явного treatment, потенциальных исходов, контроля конфаундеров, перекрытия и дизайна данных. SVM можно использовать как вспомогательную модель propensity score или outcome model, но тогда валидность определяется каузальными предпосылками, а не margin. Высокая classification accuracy не компенсирует неидентифицированный эффект.</p>`)}`
  }
};

