// Полный разбор начинается с языка задачи. Эти блоки намеренно вставляются
// рядом с первой формулой, а не складываются в отдельный «справочник»: читатель
// встречает обозначение ровно перед тем, как оно понадобится в выводе.
function notationTable(rows, title = 'Обозначения в этом разделе') {
  return `<aside class="notation-card"><div class="notation-card-title">${title}</div><dl>${rows.map(([symbol, meaning]) => `<div><dt>${symbol}</dt><dd>${meaning}</dd></div>`).join('')}</dl></aside>`;
}

function derivationStack(title, steps) {
  return `<div class="derivation-card"><div class="derivation-title">${title}</div><div class="derivation-steps">${steps.map((step, index) => `<div class="derivation-step"><span>${index + 1}</span><div><code>${step.formula}</code><p>${step.explanation}</p></div></div>`).join('')}</div></div>`;
}

function equationCard(formula, caption) {
  return `<div class="equation-card"><div>${formula}</div>${caption ? `<p>${caption}</p>` : ''}</div>`;
}


function insertTheoryBefore(kind, beforeId, outlineEntry, html) {
  const marker = `<section class="theory-block algorithm-section" id="${beforeId}">`;
  theoryPages[kind].content = theoryPages[kind].content.replace(marker, `${html}${marker}`);
  const outlineIndex = theoryPages[kind].outline.findIndex(([id]) => id === beforeId);
  theoryPages[kind].outline.splice(outlineIndex < 0 ? theoryPages[kind].outline.length : outlineIndex, 0, outlineEntry);
}


const logisticNotation = section('logistic-notation', 'база / обозначения', 'Какие числа участвуют в классификации', `
  <p>В бинарной классификации признаки остаются числовым вектором, но ответ принимает только два значения. Модель сначала строит не вероятность, а неограниченный линейный score; только затем сигмоида переводит его в интервал от 0 до 1.</p>
  ${notationTable([
    ['xᵢ ∈ ℝᵈ', 'признаки i-го объекта'],
    ['yᵢ ∈ {0,1}', 'истинный класс i-го объекта'],
    ['w ∈ ℝᵈ, b ∈ ℝ', 'обучаемые веса и смещение'],
    ['zᵢ = wᵀxᵢ+b', 'линейный score до сигмоиды'],
    ['σ(z)=1/(1+e⁻ᶻ)', 'сигмоида'],
    ['pᵢ = σ(zᵢ)', 'оценка P(Y=1|X=xᵢ)'],
    ['1−pᵢ', 'оценка P(Y=0|X=xᵢ)']
  ])}
  ${equationCard('log(pᵢ/(1−pᵢ)) = zᵢ = wᵀxᵢ+b', 'Линейны не сами вероятности, а log-odds — логарифм отношения шанса класса 1 к шансу класса 0.')}
`);

const logisticLikelihood = section('logistic-likelihood-derivation', 'вывод / log-loss', 'BCE из распределения Бернулли — по шагам', `
  <p>Для одного объекта обе ситуации можно записать одной формулой. Если yᵢ=1, останется множитель pᵢ. Если yᵢ=0, останется 1−pᵢ. Это не мнемоника, а функция вероятности бинарной случайной величины.</p>
  ${notationTable([
    ['Bernoulli(pᵢ)', 'распределение бинарной величины с вероятностью успеха pᵢ'],
    ['L(w,b)', 'правдоподобие всех меток при текущих параметрах'],
    ['ℓᵢ', 'loss на одном объекте'],
    ['J(w,b)', 'средний loss по n объектам'],
    ['log', 'натуральный логарифм']
  ], 'Новые обозначения')}
  ${derivationStack('От вероятности метки к функции потерь', [
    { formula: 'P(Yᵢ=yᵢ|xᵢ) = pᵢʸⁱ(1−pᵢ)¹⁻ʸⁱ', explanation: 'При yᵢ=1 показатель у pᵢ равен 1, а у второго множителя 0; при yᵢ=0 — наоборот.' },
    { formula: 'L(w,b) = ∏ᵢ pᵢʸⁱ(1−pᵢ)¹⁻ʸⁱ', explanation: 'Независимые наблюдения дают произведение вероятностей.' },
    { formula: 'log L = Σᵢ[yᵢlog pᵢ + (1−yᵢ)log(1−pᵢ)]', explanation: 'Логарифм превращает произведение в сумму и сохраняет положение максимума.' },
    { formula: 'ℓᵢ = −yᵢlog pᵢ − (1−yᵢ)log(1−pᵢ)', explanation: 'Меняем знак, чтобы вместо максимизации правдоподобия минимизировать loss.' },
    { formula: 'J(w,b) = 1/n · Σᵢℓᵢ', explanation: 'Усредняем потери по выборке: это binary cross-entropy, или log-loss.' }
  ])}
  <p>При истинном классе 1 loss равен −log p. Прогноз p=0.9 даёт примерно 0.105, p=0.5 — 0.693, а уверенно неверный p=0.01 — около 4.605. Поэтому log-loss различает осторожную и самоуверенную ошибку, тогда как accuracy видит только сторону порога.</p>
`);

const logisticGradientDeep = section('logistic-gradient-derivation', 'вывод / градиент BCE', 'От цепного правила к остатку p−y', `
  <p>Простая итоговая формула возникает из точного сокращения. Покажем его для одного объекта и затем усредним.</p>
  ${notationTable([
    ['ℓ', 'binary cross-entropy одного объекта'],
    ['z', 'линейный score этого объекта'],
    ['p=σ(z)', 'предсказанная вероятность класса 1'],
    ['σ′(z)=p(1−p)', 'производная сигмоиды'],
    ['xⱼ', 'j-й признак рассматриваемого объекта']
  ], 'Символы цепного правила')}
  ${derivationStack('Полная цепочка производных', [
    { formula: '∂ℓ/∂p = −y/p + (1−y)/(1−p)', explanation: 'Берём производную двух логарифмов по вероятности p.' },
    { formula: '∂p/∂z = p(1−p)', explanation: 'Это производная сигмоиды.' },
    { formula: '∂ℓ/∂z = [−y/p + (1−y)/(1−p)]p(1−p) = p−y', explanation: 'Раскрытие скобок даёт −y(1−p)+(1−y)p = p−y.' },
    { formula: '∂z/∂wⱼ = xⱼ, &nbsp; ∂z/∂b = 1', explanation: 'Score линеен по каждому параметру.' },
    { formula: '∂J/∂wⱼ = 1/n Σᵢ(pᵢ−yᵢ)xᵢⱼ, &nbsp; ∂J/∂b = 1/n Σᵢ(pᵢ−yᵢ)', explanation: 'Суммируем объектные производные и делим на размер выборки.' }
  ])}
  <p>Если модель завышает вероятность положительного класса, pᵢ−yᵢ положительно и шаг уменьшает score вдоль признаков объекта. Если занижает — остаток отрицателен и обновление повышает score. L2 добавляет к градиенту весов 2λw и предотвращает их неограниченный рост на линейно разделимых данных.</p>
`);

const logisticMetricsDeep = section('logistic-metrics-deep', 'практика / метрики', 'Почему одной accuracy недостаточно', `
  ${notationTable([
    ['TP', 'положительные объекты, верно отнесённые к положительному классу'],
    ['FP', 'отрицательные объекты, ошибочно объявленные положительными'],
    ['TN', 'отрицательные объекты, верно отнесённые к отрицательному классу'],
    ['FN', 'положительные объекты, ошибочно пропущенные'],
    ['precision', 'доля истинно положительных среди всех положительных решений модели'],
    ['recall', 'доля найденных положительных среди всех реально положительных']
  ], 'Обозначения confusion matrix')}
  <div class="metric-formula-grid"><article><span>Accuracy</span><b>(TP+TN)/(TP+FP+TN+FN)</b><p>Уместна при сопоставимых классах и цене ошибок.</p></article><article><span>Precision</span><b>TP/(TP+FP)</b><p>Отвечает: насколько можно доверять положительному решению.</p></article><article><span>Recall</span><b>TP/(TP+FN)</b><p>Отвечает: какую долю положительных случаев мы не пропустили.</p></article><article><span>F1</span><b>2PR/(P+R)</b><p>Гармоническое среднее precision P и recall R.</p></article></div>
  <p>Порог превращает вероятность в решение и одновременно меняет TP, FP, TN и FN. ROC-AUC оценивает способность ранжировать случайную положительную точку выше случайной отрицательной. На сильном дисбалансе PR-AUC часто информативнее, потому что precision напрямую реагирует на число ложных срабатываний. Ни одна метрика не выбирается «по умолчанию»: сначала фиксируется цена ошибок и сценарий применения.</p>
`);

insertTheoryBefore('logistic', 'logistic-score', ['logistic-notation', 'база / обозначения'], logisticNotation);
insertTheoryBefore('logistic', 'logistic-gradient', ['logistic-likelihood-derivation', 'вывод / log-loss'], logisticLikelihood);
insertTheoryBefore('logistic', 'logistic-boundary', ['logistic-gradient-derivation', 'вывод / градиент BCE'], logisticGradientDeep);
insertTheoryBefore('logistic', 'logistic-threshold', ['logistic-metrics-deep', 'практика / метрики'], logisticMetricsDeep);

const knnNotation = section('knn-notation', 'база / обозначения', 'Что именно значит «ближайший»', `
  ${notationTable([
    ['D={(xᵢ,yᵢ)}ᵢ₌₁ⁿ', 'обучающая выборка из n размеченных объектов'],
    ['z ∈ ℝᵈ', 'новый объект, для которого нужен прогноз'],
    ['ρ(x,z)', 'выбранная функция расстояния между двумя объектами'],
    ['N<sub>k</sub>(z)', 'множество индексов k ближайших к z train-объектов'],
    ['k', 'число соседей; гиперпараметр'],
    ['𝟙[A]', 'индикатор: 1, если условие A истинно, и 0 иначе'],
    ['c', 'кандидатный класс']
  ])}
  ${equationCard('ŷ(z) = arg max<sub>c</sub> Σ<sub>i∈Nₖ(z)</sub> 𝟙[yᵢ=c]', 'Алгоритм сначала ранжирует train-объекты по расстоянию до z, берёт первые k и выбирает класс с наибольшим числом голосов.')}
  <p>KNN ничего не «обучает» в виде коэффициентов. Его inductive bias спрятан в выборе признаков, масштаба, метрики и k. Если евклидова близость не совпадает с содержательной похожестью объектов, корректно вычисленное расстояние всё равно даст плохой прогноз.</p>
`);

const knnWorkedDistance = section('knn-worked-distance', 'пример / расстояние', 'Как один немасштабированный признак меняет соседей', `
  <p>Пусть новый объект имеет сложность задачи 6 баллов и время решения 70 минут. Сравним два train-объекта: A=(5,50), B=(8,72). В исходных единицах время численно доминирует.</p>
  ${notationTable([
    ['z=(6,70)', 'новый объект: сложность 6, время 70 минут'],
    ['A=(5,50)', 'первый кандидат-сосед'],
    ['B=(8,72)', 'второй кандидат-сосед'],
    ['μⱼ', 'среднее значение j-го признака на train'],
    ['sⱼ', 'стандартное отклонение j-го признака на train'],
    ['x′ⱼ=(xⱼ−μⱼ)/sⱼ', 'стандартизованное значение признака']
  ], 'Обозначения примера')}
  ${derivationStack('Расстояние в исходном масштабе', [
    { formula: 'ρ(z,A)=√((6−5)²+(70−50)²)=√401≈20.02', explanation: 'Разница во времени равна 20 и почти полностью определяет расстояние.' },
    { formula: 'ρ(z,B)=√((6−8)²+(70−72)²)=√8≈2.83', explanation: 'B становится намного ближе, хотя отличается по сложности на два балла.' },
    { formula: 'x′ⱼ=(xⱼ−μⱼ)/sⱼ', explanation: 'После стандартизации одна единица означает одно стандартное отклонение, а не один балл или одну минуту.' }
  ])}
  <p>Масштабирование не гарантирует идеальную метрику, но убирает случайное преимущество единиц измерения. μⱼ и sⱼ считают только на train, затем теми же значениями преобразуют validation, test и новые объекты; иначе возникает утечка данных.</p>
`);

insertTheoryBefore('knn', 'knn-distance', ['knn-notation', 'база / обозначения'], knnNotation);
insertTheoryBefore('knn', 'knn-scaling', ['knn-worked-distance', 'пример / расстояние'], knnWorkedDistance);

const treeNotation = section('tree-notation', 'база / обозначения', 'Из каких множеств строится дерево', `
  ${notationTable([
    ['S', 'множество train-объектов, попавших в текущую вершину'],
    ['|S|', 'число объектов в этой вершине'],
    ['j', 'номер признака, выбранного для вопроса'],
    ['t', 'порог разбиения'],
    ['s=(j,t)', 'кандидатный split: предикат xⱼ≤t'],
    ['S<sub>L</sub>', 'левая часть: объекты, для которых xⱼ≤t'],
    ['S<sub>R</sub>', 'правая часть: объекты, для которых xⱼ&gt;t'],
    ['p<sub>k</sub>', 'доля класса k среди объектов текущей вершины'],
    ['I(S)', 'impurity множества S'],
    ['ΔI(s)', 'уменьшение impurity после split s']
  ])}
  ${equationCard('ΔI(s) = I(S) − |S<sub>L</sub>|/|S| · I(S<sub>L</sub>) − |S<sub>R</sub>|/|S| · I(S<sub>R</sub>)', 'Дочерние impurity взвешиваются числом объектов. Иначе отделение одного чистого объекта выглядело бы слишком выгодным.')}
`);

const treeWorkedSplit = section('tree-worked-split', 'пример / Gini', 'Полный расчёт одного кандидатного split', `
  <p>В вершине 10 заявок: 6 одобрены и 4 отклонены. Кандидатный предикат делит их так: слева 4 одобрены и 1 отклонена, справа 2 одобрены и 3 отклонены.</p>
  ${notationTable([
    ['Gini(S)=1−Σₖpₖ²', 'критерий неоднородности для классификации'],
    ['p₀, p₁', 'доли двух классов в рассматриваемом множестве'],
    ['I<sub>after</sub>', 'взвешенная impurity после разбиения'],
    ['ΔI', 'gain: impurity до split минус impurity после него']
  ], 'Обозначения расчёта')}
  ${derivationStack('Считаем gain', [
    { formula: 'Gini(S)=1−(6/10)²−(4/10)²=0.48', explanation: 'Это неоднородность родительской вершины.' },
    { formula: 'Gini(S<sub>L</sub>)=1−(4/5)²−(1/5)²=0.32', explanation: 'Левая вершина достаточно чистая, но содержит один объект второго класса.' },
    { formula: 'Gini(S<sub>R</sub>)=1−(2/5)²−(3/5)²=0.48', explanation: 'Правая вершина смешана сильнее.' },
    { formula: 'I<sub>after</sub>=5/10·0.32 + 5/10·0.48 = 0.40', explanation: 'Обе дочерние вершины содержат по пять объектов, поэтому веса равны 1/2.' },
    { formula: 'ΔI=0.48−0.40=0.08', explanation: 'Кандидат уменьшает impurity на 0.08. Алгоритм сравнит это значение с gain всех остальных предикатов.' }
  ])}
  <p>Жадный алгоритм выбирает лучший split <em>сейчас</em>, не перебирая все будущие деревья. Поэтому локально максимальный gain не гарантирует глобально оптимальную структуру, а ограничение глубины и минимального листа остаются важными гиперпараметрами.</p>
`);

insertTheoryBefore('tree', 'tree-predicates', ['tree-notation', 'база / обозначения'], treeNotation);
insertTheoryBefore('tree', 'tree-regression', ['tree-worked-split', 'пример / Gini'], treeWorkedSplit);

const svmNotation = section('svm-notation', 'база / обозначения', 'Язык зазора и ограничений', `
  ${notationTable([
    ['xᵢ ∈ ℝᵈ', 'признаки i-го объекта'],
    ['yᵢ ∈ {−1,+1}', 'класс объекта в удобной для SVM кодировке'],
    ['f(x)=wᵀx+b', 'линейный score'],
    ['w', 'вектор нормали к разделяющей гиперплоскости'],
    ['b', 'смещение гиперплоскости'],
    ['yᵢf(xᵢ)', 'функциональный margin объекта: положителен при верной стороне границы'],
    ['‖w‖₂', 'евклидова длина вектора w'],
    ['γᵢ=yᵢf(xᵢ)/‖w‖₂', 'геометрический margin i-го объекта'],
    ['C&gt;0', 'цена нарушений зазора в soft-margin SVM']
  ])}
  ${equationCard('граница: f(x)=0; &nbsp; уровни зазора: f(x)=−1 и f(x)=+1', 'Умножение w и b на одну константу не меняет границу. Условия yᵢf(xᵢ)≥1 фиксируют масштаб параметров.')}
`);

const svmMarginDerivation = section('svm-margin-derivation', 'вывод / ширина зазора', 'Почему оптимизируется именно норма весов', `
  <p>Расстояние от точки x до гиперплоскости wᵀx+b=0 равно |wᵀx+b|/‖w‖₂. Ближайшие объекты классов на канонических уровнях имеют score −1 и +1.</p>
  ${notationTable([
    ['x⁺', 'точка на опорной плоскости положительного класса: f(x⁺)=+1'],
    ['x⁻', 'точка на опорной плоскости отрицательного класса: f(x⁻)=−1'],
    ['margin', 'расстояние между двумя опорными плоскостями'],
    ['ξᵢ≥0', 'slack-переменная: величина нарушения условия margin для объекта i']
  ], 'Новые обозначения')}
  ${derivationStack('Расстояние между опорными плоскостями', [
    { formula: 'distance(x, f=0)=|wᵀx+b|/‖w‖₂', explanation: 'Проекция смещения на единичную нормаль w/‖w‖₂.' },
    { formula: 'distance(f=+1,f=0)=1/‖w‖₂', explanation: 'Для точки уровня +1 числитель равен единице.' },
    { formula: 'margin=2/‖w‖₂', explanation: 'Складываем одинаковые расстояния от уровней +1 и −1 до середины.' },
    { formula: 'max 2/‖w‖₂ ⇔ min 1/2‖w‖²₂', explanation: 'Максимизировать обратную норму эквивалентно минимизировать её квадрат; коэффициент 1/2 упрощает производную.' },
    { formula: 'min 1/2‖w‖²₂ + (C/n)Σᵢξᵢ, &nbsp; yᵢf(xᵢ)≥1−ξᵢ, &nbsp; ξᵢ≥0', explanation: 'Soft margin разрешает нарушения. Используем средний hinge-loss, как в лаборатории: каждое нарушение оплачивается с весом C/n.' }
  ])}
  <p>В hinge-форме оптимальное ξᵢ равно max(0,1−yᵢf(xᵢ)). Объекты с yᵢf(xᵢ)&gt;1 не дают вклада в loss; объекты на границе или внутри зазора определяют решение и называются опорными.</p>
`);

const svmMulticlass = section('svm-multiclass', 'расширение / несколько классов', 'Как бинарный SVM превращают в многоклассовый', `
  ${notationTable([
    ['K', 'число классов'],
    ['f<sub>k</sub>(x)', 'score классификатора класса k'],
    ['arg max<sub>k</sub>', 'индекс класса с наибольшим score'],
    ['OvR', 'one-vs-rest: один класс против объединения остальных'],
    ['OvO', 'one-vs-one: отдельный классификатор для каждой пары классов']
  ])}
  <p>В OvR обучают K бинарных моделей. Для объекта считают K score и выбирают класс с максимальным значением: ŷ=arg max<sub>k</sub>f<sub>k</sub>(x). Но шкалы разных бинарных моделей не обязаны быть идеально сопоставимы, особенно при разном дисбалансе.</p>
  <p>В OvO обучают K(K−1)/2 парных моделей и агрегируют их голоса. Моделей больше, зато каждая видит только два класса. Оба подхода являются конструкциями вокруг бинарного SVM; выбор проверяют по качеству и вычислительной стоимости на конкретной задаче.</p>
`);

insertTheoryBefore('svm', 'svm-hard-margin', ['svm-notation', 'база / обозначения'], svmNotation);
insertTheoryBefore('svm', 'svm-dual', ['svm-margin-derivation', 'вывод / ширина зазора'], svmMarginDerivation);
insertTheoryBefore('svm', 'svm-limits', ['svm-multiclass', 'расширение / несколько классов'], svmMulticlass);


const logisticRankingMetrics = section('logistic-ranking-metrics', 'метрики / ROC, PR и AUC', 'Как оценивать score без фиксированного порога', `
  <p>Логистическая регрессия выдаёт score z и вероятность p, а бинарное решение появляется только после выбора порога t. Меняя t от +∞ до −∞, мы получаем целое семейство классификаторов.</p>
  ${notationTable([
    ['t', 'порог: класс 1 выбирается при p≥t'],
    ['TPR=TP/(TP+FN)', 'true positive rate; совпадает с recall'],
    ['FPR=FP/(FP+TN)', 'false positive rate'],
    ['ROC', 'кривая точек (FPR(t),TPR(t)) при всех порогах'],
    ['AUC-ROC', 'площадь под ROC-кривой'],
    ['PR', 'кривая precision–recall'],
    ['AP', 'average precision: пороговое суммирование precision по найденным положительным']
  ])}
  ${equationCard('AUC-ROC = P(score(x⁺) &gt; score(x⁻)) + 1/2·P(score(x⁺)=score(x⁻))', 'AUC - вероятность правильного порядка случайной пары из разных классов; совпадение score засчитывается за половину.')}
  <p>AUC=0.5 соответствует случайному ранжированию, AUC=1 — идеальному порядку. Метрика не проверяет калибровку вероятностей и может выглядеть высокой при сильном дисбалансе, даже когда верх списка содержит слишком много ложных срабатываний. В таких задачах PR-кривая и AP чаще отвечают практическому вопросу: сколько положительных найдено при данном уровне точности.</p>
  <div class="theory-callout"><b>Порог всё равно нужен.</b> ROC/PR сравнивают ранжирование, но не выбирают рабочее решение. Финальный t определяют на validation по цене FP и FN, ограничениям на recall/precision или ожидаемой пользе. Test используют один раз после фиксации правила.</div>
`);

const logisticSoftmax = section('logistic-softmax', 'расширение / softmax', 'Многоклассовая логистическая регрессия', `
  <p>Для K взаимоисключающих классов модель строит отдельный score каждого класса, а softmax нормирует их в распределение вероятностей с суммой 1.</p>
  ${notationTable([
    ['K', 'число классов'],
    ['w<sub>k</sub>, b<sub>k</sub>', 'веса и смещение класса k'],
    ['z<sub>ik</sub>=w<sub>k</sub>ᵀxᵢ+b<sub>k</sub>', 'score класса k для объекта i'],
    ['p<sub>ik</sub>', 'вероятность класса k для объекта i'],
    ['yᵢ∈{1,…,K}', 'номер истинного класса'],
    ['𝟙[yᵢ=k]', 'one-hot индикатор истинного класса']
  ])}
  ${derivationStack('Softmax и cross-entropy', [
    { formula: 'p<sub>ik</sub>=exp(z<sub>ik</sub>)/Σ<sub>c=1</sub><sup>K</sup>exp(z<sub>ic</sub>)', explanation: 'Экспоненты положительны, а деление на их сумму гарантирует Σₖpᵢₖ=1.' },
    { formula: 'P(Yᵢ=yᵢ|xᵢ)=∏<sub>k=1</sub><sup>K</sup>p<sub>ik</sub><sup>𝟙[yᵢ=k]</sup>', explanation: 'Все множители, кроме вероятности истинного класса, возводятся в нулевую степень.' },
    { formula: 'J=−1/n·ΣᵢΣₖ𝟙[yᵢ=k]log p<sub>ik</sub>', explanation: 'Отрицательный log-likelihood даёт многоклассовую cross-entropy.' },
    { formula: '∂J/∂z<sub>ik</sub>=1/n·(p<sub>ik</sub>−𝟙[yᵢ=k])', explanation: 'Градиент снова равен «предсказанная вероятность минус истинный индикатор».' }
  ])}
  <p>Ко всем score можно прибавить одну константу без изменения вероятностей, поэтому для численной устойчивости перед exp вычитают maxₖzᵢₖ. Для отчётности используют macro-усреднение метрик (равный вес каждому классу) или micro-усреднение (сначала суммируются TP/FP/FN по классам); выбор зависит от того, важны ли редкие классы наравне с массовыми.</p>
`);

const logisticCategorical = section('logistic-categorical', 'данные / категории', 'Как категориальный признак становится числом', `
  ${notationTable([
    ['c', 'значение категориального признака'],
    ['M', 'число известных категорий'],
    ['e<sub>c</sub>∈{0,1}ᴹ', 'one-hot вектор категории c'],
    ['N<sub>c</sub>', 'число train-объектов категории c'],
    ['S<sub>c</sub>', 'сумма target по train-объектам категории c'],
    ['α&gt;0', 'сила сглаживания target encoding'],
    ['μ', 'глобальное среднее target на train']
  ])}
  ${equationCard('TE(c) = (S<sub>c</sub> + αμ)/(N<sub>c</sub> + α)', 'Сглаженный target encoding тянет редкие категории к глобальному среднему и уменьшает variance.')}
  <p>One-hot безопасен при умеренном M, но расширяет размерность. Хэширование ограничивает размер пространства, допуская коллизии. Target encoding компактен, но особенно опасен утечкой: значение строки нельзя считать с использованием её собственного target. На train используют out-of-fold или ordered-схему; для validation/test статистики фиксируют по train.</p>
`);

insertTheoryBefore('logistic', 'logistic-threshold', ['logistic-ranking-metrics', 'метрики / ROC, PR и AUC'], logisticRankingMetrics);
insertTheoryBefore('logistic', 'logistic-threshold', ['logistic-softmax', 'расширение / softmax'], logisticSoftmax);
insertTheoryBefore('logistic', 'logistic-threshold', ['logistic-categorical', 'данные / категории'], logisticCategorical);

const treeCategorical = section('tree-categorical', 'данные / категории', 'Как дерево задаёт вопрос категориальному признаку', `
  <p>Для числового признака естественен порог xⱼ≤t. Для категории порога нет: корректный бинарный вопрос имеет вид xⱼ∈A, где A — подмножество допустимых значений.</p>
  ${notationTable([
    ['C={c₁,…,c<sub>M</sub>}', 'множество M категорий признака'],
    ['A⊂C', 'подмножество категорий, отправляемых в левую ветвь'],
    ['2<sup>M−1</sup>−1', 'число нетривиальных разбиений категорий на две неупорядоченные группы'],
    ['μ<sub>c</sub>', 'средний target среди train-объектов категории c'],
    ['xⱼ∈A', 'предикат категориального split']
  ])}
  <p>Полный перебор подмножеств экспоненциально дорог. В бинарной классификации категории можно упорядочить по доле положительного класса μ<sub>c</sub> и проверять только M−1 порогов в этом порядке. Статистику считают внутри текущей вершины по train-объектам; редкие категории дают шумные оценки и требуют минимального размера листа или объединения.</p>
  <p>One-hot перед обычным деревом разрешает вопросы «категория равна c?», но не всегда эффективно группирует похожие категории. Нативные реализации могут искать групповые split, применять ordered target statistics и отдельно направлять пропуски. Неизвестная категория на inference должна иметь заранее определённую ветвь — это часть модели, а не исключительная ситуация.</p>
`);

insertTheoryBefore('tree', 'tree-missing', ['tree-categorical', 'данные / категории'], treeCategorical);

const svmDualNotation = section('svm-dual-notation', 'вывод / dual обозначения', 'Что означают коэффициенты двойственной задачи', `
  ${notationTable([
    ['αᵢ≥0', 'множитель Лагранжа для ограничения i-го train-объекта'],
    ['SV={i:αᵢ&gt;0}', 'индексы опорных векторов'],
    ['⟨xᵢ,xⱼ⟩=xᵢᵀxⱼ', 'скалярное произведение двух объектов'],
    ['K(x,z)', 'ядро: скалярное произведение объектов после неявного отображения'],
    ['φ(x)', 'вектор признаков в новом, возможно высокоразмерном пространстве']
  ])}
  ${derivationStack('Как ограничения входят в решение', [
    { formula: 'ℒ(w,b,α)=1/2‖w‖²−Σᵢαᵢ[yᵢ(wᵀxᵢ+b)−1]', explanation: 'К objective hard-margin добавляются ограничения с неотрицательными множителями.' },
    { formula: '∂ℒ/∂w=0  ⇒  w=Σᵢαᵢyᵢxᵢ', explanation: 'Оптимальная нормаль является линейной комбинацией train-объектов.' },
    { formula: '∂ℒ/∂b=0  ⇒  Σᵢαᵢyᵢ=0', explanation: 'Это равенство становится ограничением dual-задачи.' },
    { formula: 'αᵢ[yᵢf(xᵢ)−1]=0', explanation: 'Complementary slackness: либо ограничение строго выполнено и αᵢ=0, либо объект лежит на margin и может иметь αᵢ&gt;0.' },
    { formula: 'f(x)=Σ<sub>i∈SV</sub>αᵢyᵢK(xᵢ,x)+b', explanation: 'Нулевые αᵢ исчезают; ядро заменяет явное скалярное произведение φ(xᵢ)ᵀφ(x).' }
  ])}
  <p>Ядро должно быть положительно полуопределённым, чтобы соответствовать скалярному произведению некоторого пространства и сохранять выпуклость dual-задачи. Параметры ядра и C выбирают по validation; ядро расширяет класс границ, но не исправляет плохие признаки или сдвиг данных.</p>
`);

insertTheoryBefore('svm', 'svm-dual', ['svm-dual-notation', 'вывод / dual обозначения'], svmDualNotation);

function addNotationToSection(kind, id, rows, title = 'Обозначения раздела') {
  const heading = new RegExp(`(<section class="theory-block algorithm-section" id="${id}"><small>[\\s\\S]*?</small><h2>[\\s\\S]*?</h2>)`);
  theoryPages[kind].content = theoryPages[kind].content.replace(heading, match => `${match}${notationTable(rows, title)}`);
}

